\begin{aligned}
ScanR(pvar(y),R;\rho)&=(pvar(z),R[y\mapsto var(z)]),\quad var(z)=\widehat\rho(y),\\
ScanR(pdot(t),R;\rho)&=(pdot(Sim(t,R)),R),\\
R_0&=R,\quad(q'_j,R_{j+1})=ScanR(q_j,R_j;\rho),\\
ScanR(pcon(k,\bar q),R;\rho)&=(pcon(k,\langle q'_j:j<|\bar q|\rangle),R_{|\bar q|}).
\end{aligned}

\begin{aligned}
ScanD(pvar(y),\delta,X)&=(pvar(y),\delta\setminus y,X\cup\{y\}),\\
ScanD(pdot(t),\delta,X)&=(pdot(Sim(t,\delta)),\delta,X),\\
(\delta_0,X_0)&=(\delta,X),\quad(q'_j,\delta_{j+1},X_{j+1})=ScanD(q_j,\delta_j,X_j),\\
ScanD(pcon(k,\bar q),\delta,X)&=(pcon(k,\langle q'_j:j<|\bar q|\rangle),\delta_m,X_m),\quad m=|\bar q|.
\end{aligned}
